import csv
import io
from collections import Counter

def parse_csv(raw_csv: str):
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    old_limit = csv.field_size_limit()
    try:
        csv.field_size_limit(max(old_limit, len(raw_csv) + 1))
        records = list(csv.reader(io.StringIO(raw_csv, newline=""), delimiter=";", quotechar='"'))
    finally:
        csv.field_size_limit(old_limit)

    if not records:
        return {"columns": [], "rows": []}

    columns = records[0]
    rows = records[1:]

    widths = Counter(len(row) for row in rows if row)
    if widths and columns:
        common_width, count = widths.most_common(1)[0]
        if (
            common_width == len(columns) + 1
            and count >= 2
            and count * 2 > sum(widths.values())
            and len(set(columns)) < len(columns)
        ):
            columns = [""] + columns

    width = max([len(columns)] + [len(row) for row in rows])
    columns = columns + [""] * (width - len(columns))
    rows = [row + [""] * (width - len(row)) for row in rows]

    return {"columns": columns, "rows": rows}
